class Solution {
  public int[] findDiagonalOrder(int[][] mat) {
    int m = mat.length, n = mat[0].length;
    int[] res = new int[m * n];
    int k = 0;
    for (int d = 0; d < m + n - 1; d++) {
      if (d % 2 == 0) { // up-right: row from high to low
        for (int r = Math.min(d, m - 1); r >= 0 && d - r < n; r--) res[k++] = mat[r][d - r];
      } else {
        for (int c = Math.min(d, n - 1); c >= 0 && d - c < m; c--) res[k++] = mat[d - c][c];
      }
    }
    return res;
  }
}
